for (const [key, value] of Object.entries(catalog)) {
  catalog[key] = value.replace(/bate-papo/g, 'conversa').replace(/Bate-papo/g, 'Conversa')
    .replace(/\bnovos conversas\b/g, 'novas conversas').replace(/\bnovo conversa\b/g, 'nova conversa')
    .replace(/\bseus conversas\b/g, 'suas conversas').replace(/\bseu conversa\b/g, 'sua conversa')
    .replace(/\b[oO] conversa\b/g, match => match[0] === 'O' ? 'A conversa' : 'a conversa')
    .replace(/\bdo conversa\b/g, 'da conversa').replace(/\bno conversa\b/g, 'na conversa')
    .replace(/\bum conversa\b/g, 'uma conversa')
    .replace(/\b(conversas?) (compartilhad|salv|abert|selecionad|remot|ativ|vazi|iniciad)o(s?)\b/g, '$1 $2a$3')
  if (/^(?:Qwen|Llama|Hermes|DeepSeek|Gemma|Mistral|Phi[- ]|nomic-|whisper-|Piper|Kokoro)\b/.test(key) && key.length < 70 && !/[,!?]|\.$/.test(key)) catalog[key] = key
  if (Object.hasOwn(reviewed, key.trim())) {
    const leading = key.match(/^\s*/)[0]
    const trailing = key.match(/\s*$/)[0]
    catalog[key] = leading + reviewed[key.trim()] + trailing
  }
}
Object.assign(catalog, reviewed)
