// Model names are identifiers, regardless of how a translation engine reads them.
for (const name of ['src/api/discover.ts', 'src/lib/model-compatibility.ts', 'src/lib/systemCheck.ts']) {
  const file = new URL('../' + name, import.meta.url)
  const sf = ts.createSourceFile(name, readFileSync(file, 'utf8'), ts.ScriptTarget.Latest, true)
  function visit(node) {
    if (ts.isPropertyAssignment(node) && node.name.getText(sf).replace(/['"]/g, '') === 'name' && ts.isStringLiteral(node.initializer) && Object.hasOwn(catalog, node.initializer.text)) catalog[node.initializer.text] = node.initializer.text
    ts.forEachChild(node, visit)
  }
  visit(sf)
}
// Portuguese strings already owned by the small navigation catalog are not
// English source keys. Exclude them so nested presentation cannot translate twice.
const nav = ts.createSourceFile('i18n.ts', readFileSync(new URL('../src/lib/i18n.ts', import.meta.url), 'utf8'), ts.ScriptTarget.Latest, true)
const navigation = { ptBR: [], en: [] }
function navVisit(node) {
  if (ts.isVariableDeclaration(node) && Object.hasOwn(navigation, node.name.getText(nav))) {
    const object = ts.isAsExpression(node.initializer) ? node.initializer.expression : node.initializer
    for (const prop of object.properties ?? []) if (ts.isPropertyAssignment(prop) && ts.isStringLiteral(prop.initializer)) navigation[node.name.getText(nav)].push(prop.initializer.text)
  }
  ts.forEachChild(node, navVisit)
}
navVisit(nav)
for (const value of navigation.ptBR) if (!navigation.en.includes(value)) delete catalog[value]
writeFileSync(path, JSON.stringify(Object.fromEntries(Object.entries(catalog).sort()), null, 2) + '\n')
console.log(`Reviewed terminology in ${Object.keys(catalog).length} local catalog entries`)
